        is($result, ['d', 4], 'Shift2 returns the single key-value pair');
        is(scalar(keys %$hash), 0, 'Hash is empty after Shift2');
    }
}

# Test case: Shift2 on an invalid object
{
    my $invalid_object = 'not_a_hash';
